const today = frappe.datetime.get_today(); // format: YYYY-MM-DD
const currentYear = today.split("-")[0]; // Ambil tahun
const currentMonth = today.split("-")[1]; // Ambil bulan

// Step 2: Hitung tanggal pertama bulan berikutnya
const firstDayOfNextMonth = new Date(currentYear, currentMonth, 1);

// Step 3: Kurangi satu hari untuk mendapatkan tanggal terakhir bulan ini
const lastDayOfMonth = new Date(firstDayOfNextMonth - 1);
const lastDayFormatted = frappe.datetime.obj_to_str(lastDayOfMonth); // Format tanggal sesuai Frappe

// Tanggal pertama bulan ini
const firstDayOfMonth = `${currentYear}-${currentMonth}-01`;


var script = document.createElement('script');
script.src = 'https://cdn.jsdelivr.net/npm/chart.js';
script.defer = true;

script.onload = function() {
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Absensi",
            fields: ["karyawan", "tipe", "izin"],
            filters: [
                [
                    'waktu_absen', 'between', [firstDayOfMonth, lastDayFormatted]
                ]
            ],
            limit_page_length: 1000
        },
        callback: function(response) {
            const data = response.message;

            // Inisialisasi counter
            let hadir = 0;
            let izin = 0;
            let tidak_hadir = 0;

            data.forEach(item => {
                if (item.tipe === "In") {
                    hadir++;
                } else if (item.izin === 1) {
                    izin++;
                } else {
                    tidak_hadir++;
                }
            });

            const labels = ['Hadir', 'Izin', 'Tidak Hadir'];
            const values = [hadir, izin, tidak_hadir];

            const ctx = root_element.querySelector('#myPieChart').getContext('2d');
            const myPieChart = new Chart(ctx, {
                type: 'pie',
                data: {
                    labels: labels,
                    datasets: [{
                        label: 'Status Kehadiran',
                        data: values,
                        backgroundColor: [
                            'rgba(75, 192, 192, 0.7)', // Hadir: hijau-biru
                            'rgba(255, 205, 86, 0.7)', // Izin: kuning
                            'rgba(255, 99, 132, 0.7)' // Tidak Hadir: merah
                        ],
                        borderColor: [
                            'rgba(75, 192, 192, 1)',
                            'rgba(255, 205, 86, 1)',
                            'rgba(255, 99, 132, 1)'
                        ],
                        borderWidth: 1
                    }]
                },
                options: {
                    responsive: true,
                    plugins: {
                        legend: {
                            position: 'top',
                        },
                        title: {
                            display: true,
                            text: 'Distribusi Kehadiran Karyawan'
                        },
                        tooltip: {
                            callbacks: {
                                label: function(context) {
                                    const total = context.dataset.data.reduce((sum, value) => sum + value, 0);
                                    const currentValue = context.raw;
                                    const percentage = ((currentValue / total) * 100).toFixed(1);
                                    return `${context.label}: ${currentValue} (${percentage}%)`;
                                }
                            }
                        }
                    }
                }

            });
        }
    });
};

document.head.appendChild(script);

const today = frappe.datetime.get_today(); // format: YYYY-MM-DD
const currentYear = today.split("-")[0];  // Ambil tahun
const currentMonth = today.split("-")[1]; // Ambil bulan

// Step 2: Hitung tanggal pertama bulan berikutnya
const firstDayOfNextMonth = new Date(currentYear, currentMonth, 1);

// Step 3: Kurangi satu hari untuk mendapatkan tanggal terakhir bulan ini
const lastDayOfMonth = new Date(firstDayOfNextMonth - 1);
const lastDayFormatted = frappe.datetime.obj_to_str(lastDayOfMonth); // Format tanggal sesuai Frappe

// Tanggal pertama bulan ini
const firstDayOfMonth = `${currentYear}-${currentMonth}-01`;

// Step 1: Ambil semua data karyawan dulu (id dan nama lengkap)
frappe.call({
    method: "frappe.client.get_list",
    args: {
        doctype: "Karyawan",
        fields: ["name", "nama_lengkap"],
        limit_page_length: 1000
    },
    callback: function(karyawanResponse) {
        const karyawanData = karyawanResponse.message;

        // Buat dictionary: {id_karyawan: nama_lengkap}
        const karyawanMap = {};
        karyawanData.forEach(item => {
            karyawanMap[item.name] = item.nama_lengkap;
        });

        // Step 2: Setelah itu, ambil absensi
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Absensi",
                fields: ["karyawan", "tipe"],
                filters: [[
                    'waktu_absen', 'between', [firstDayOfMonth, lastDayFormatted]
                ]],
                limit_page_length: 1000
            },
            callback: function(absensiResponse) {
                const data = absensiResponse.message;

                let absensiCount = {};

                // Hitung jumlah 'In' per karyawan
                data.forEach(item => {
                    if (item.tipe === "In") {
                        if (item.karyawan) {
                            if (absensiCount[item.karyawan]) {
                                absensiCount[item.karyawan]++;
                            } else {
                                absensiCount[item.karyawan] = 1;
                            }
                        }
                    }
                });

                // Convert jadi array, lalu sort descending
                const sortedData = Object.entries(absensiCount)
                    .sort((a, b) => b[1] - a[1])
                    .slice(0, 5);

                const tbody = root_element.querySelector('#absensiTable tbody');

                // Masukkan ke tabel
                sortedData.forEach((item, index) => {
                    const [karyawanId, total] = item;
                    const namaLengkap = karyawanMap[karyawanId] || karyawanId; // fallback ke ID kalau nama tidak ada

                    const row = document.createElement('tr');
                    row.innerHTML = `
                        <td style="border: 1px solid #ddd; padding: 8px;">${index + 1}</td>
                        <td style="border: 1px solid #ddd; padding: 8px;">${namaLengkap}</td>
                        <td style="border: 1px solid #ddd; padding: 8px;">${total}</td>
                    `;
                    tbody.appendChild(row);
                });
            }
        });
    }
});

